// Simple endless‑runner based on IDEA.md
// Canvas with id="game"
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 800;
  const height = canvas.height = canvas.clientHeight || 600;

  // ----- Ship -----
  const ship = {
    x: width * 0.1,
    y: height / 2,
    size: 20,
    speed: 4,
    angle: 0,
    radius: 12,
  };
  const keys = {};
  window.addEventListener('keydown', e => (keys[e.key] = true));
  window.addEventListener('keyup', e => (keys[e.key] = false));

  // ----- Asteroids -----
  const asteroids = [];
  function spawnAsteroid() {
    const size = Math.random() * 30 + 15;
    asteroids.push({
      x: width + size,
      y: Math.random() * height,
      r: size,
      vx: -(Math.random() * 2 + 2),
      angle: Math.random() * Math.PI * 2,
      av: (Math.random() - 0.5) * 0.04,
    });
  }
  let asteroidTimer = 0;

  // ----- Helpers -----
  function drawShip() {
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.beginPath();
    ctx.moveTo(ship.size, 0);
    ctx.lineTo(-ship.size / 2, ship.size / 2);
    ctx.lineTo(-ship.size / 2, -ship.size / 2);
    ctx.closePath();
    ctx.fillStyle = '#0f0';
    ctx.fill();
    ctx.restore();
  }

  function drawAsteroid(a) {
    ctx.save();
    ctx.translate(a.x, a.y);
    ctx.rotate(a.angle);
    ctx.beginPath();
    const sides = Math.floor(Math.random() * 5) + 5;
    for (let i = 0; i < sides; i++) {
      const theta = (i / sides) * Math.PI * 2;
      const rad = a.r * (0.7 + Math.random() * 0.3);
      ctx.lineTo(Math.cos(theta) * rad, Math.sin(theta) * rad);
    }
    ctx.closePath();
    ctx.strokeStyle = '#fff';
    ctx.stroke();
    ctx.restore();
  }

  function update() {
    // Input handling
    if (keys.ArrowUp || keys.w) ship.y -= ship.speed;
    if (keys.ArrowDown || keys.s) ship.y += ship.speed;
    if (keys.ArrowLeft || keys.a) ship.x -= ship.speed;
    if (keys.ArrowRight || keys.d) ship.x += ship.speed;
    // Keep inside canvas
    ship.x = Math.max(0, Math.min(width, ship.x));
    ship.y = Math.max(0, Math.min(height, ship.y));
    ship.angle = Math.atan2(
      (keys.ArrowDown || keys.s) - (keys.ArrowUp || keys.w),
      (keys.ArrowRight || keys.d) - (keys.ArrowLeft || keys.a)
    );

    // Asteroid logic
    asteroidTimer -= 1;
    if (asteroidTimer <= 0) {
      spawnAsteroid();
      asteroidTimer = Math.random() * 60 + 30; // 0.5‑2 sec
    }
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.x += a.vx;
      a.angle += a.av;
      if (a.x + a.r < 0) asteroids.splice(i, 1);
    }

    // Collision detection (circle‑based)
    for (const a of asteroids) {
      const dx = a.x - ship.x;
      const dy = a.y - ship.y;
      const dist = Math.hypot(dx, dy);
      if (dist < a.r + ship.radius) {
        // Game over – stop animation
        cancelAnimationFrame(frameId);
        ctx.fillStyle = 'red';
        ctx.font = '48px sans-serif';
        ctx.fillText('Game Over', width / 2 - 120, height / 2);
        return;
      }
    }
  }

  function render() {
    ctx.clearRect(0, 0, width, height);
    drawShip();
    for (const a of asteroids) drawAsteroid(a);
  }

  function loop() {
    update();
    render();
    frameId = requestAnimationFrame(loop);
  }
  let frameId = requestAnimationFrame(loop);
})();
